        Room standard = RoomService.getRoomByNumber(101);
        assertEquals(2, standard.getCapacity());

        Room deluxe = RoomService.getRoomByNumber(201);
        assertEquals(3, deluxe.getCapacity());

        Room suite = RoomService.getRoomByNumber(301);
        assertEquals(4, suite.getCapacity());
    }

    @Test
    public void testNightlyRates() {
        Room standard = RoomService.getRoomByNumber(101);
        assertEquals("249.90", standard.getNightlyRate().toString());

        Room deluxe = RoomService.getRoomByNumber(201);
        assertEquals("389.90", deluxe.getNightlyRate().toString());

        Room suite = RoomService.getRoomByNumber(301);
        assertEquals("579.90", suite.getNightlyRate().toString());
    }
}

